const b=$input.first().json.body||$input.first().json;
const data=b.data||b;const payload=data.payload||data;
const et=(data.event_type||'').toLowerCase();
const map={'call.answered':'call_connected','call.recording.saved':'recording_ready','call.hangup':'call_ended','call.machine.detection.ended':'amd_result'};
const event_type=map[et]||'call_ended';
let amd='unknown';
if(event_type==='amd_result'){const r=(payload.result||'').toLowerCase();amd=r.includes('machine')?'machine':r.includes('human')?'human':'unknown';}
const ev={event_type,call_sid:payload.call_control_id||payload.id||'',from:payload.from||'',to:payload.to||'',recording_url:payload.recording_urls?.mp3||payload.recording_url||'',amd_result:amd,duration_sec:payload.duration_secs||0,provider:'telnyx',raw:b};
if(event_type==='call_connected'){
  const bucket=($env.STORAGE_BUCKET_URL||'').replace(/\/$/, '');
  const texml='<?xml version="1.0" encoding="UTF-8"?><Response><Play>'+bucket+'/ouverture.mp3</Play><Record action="'+($env.N8N_WEBHOOK_URL||'').replace(/\/$/, '')+'/telephony/telnyx/transcribe" maxLength="15" timeout="3"/></Response>';
  return [{json:{normalized:ev,texml}}];
}
await this.helpers.httpRequest({method:'POST',url:($env.N8N_WEBHOOK_URL||'').replace(/\/$/, '')+'/renov/conversation',body:ev,json:true});
return [{json:ev}];
